"""backend/tools/hashed_subset.py — what the Docker image's Python install
trusts: every package it installs comes out of the committed lock, with the
lock's hashes, or the build fails."""

import importlib.util
from pathlib import Path

import pytest

BACKEND = Path(__file__).resolve().parents[3]

_spec = importlib.util.spec_from_file_location("hashed_subset", BACKEND / "tools" / "hashed_subset.py")
assert _spec and _spec.loader
hashed_subset = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(hashed_subset)

LOCK = """\
# This file was autogenerated by uv via the following command:
#    backend/bin/compile-requirements
aiofiles==25.1.0 \\
    --hash=sha256:aaaa \\
    --hash=sha256:bbbb
    # via -r requirements.in
greenlet==3.5.6 ; platform_machine == 'aarch64' or platform_machine == 'x86_64' \\
    --hash=sha256:cccc
    # via sqlalchemy
python-jose==3.5.0 \\
    --hash=sha256:dddd
unhashed==1.0
"""


def test_cuts_the_resolved_entries_out_of_the_lock_with_their_hashes():
    out = hashed_subset.hashed_subset(LOCK, "python_jose==3.5.0\naiofiles==25.1.0\n")

    # Resolver spelling (python_jose) finds the lock's python-jose; comments
    # and packages the runtime does not need stay behind.
    assert out == (
        "python-jose==3.5.0 \\\n"
        "    --hash=sha256:dddd\n"
        "aiofiles==25.1.0 \\\n"
        "    --hash=sha256:aaaa \\\n"
        "    --hash=sha256:bbbb\n"
    )


def test_markers_survive_so_the_subset_installs_on_the_platform_that_needs_it():
    out = hashed_subset.hashed_subset(LOCK, "greenlet==3.5.6\n")
    assert out.startswith("greenlet==3.5.6 ; platform_machine == 'aarch64'")
    assert "--hash=sha256:cccc" in out


@pytest.mark.parametrize(
    "resolved, complaint",
    [
        ("requests==2.0.0\n", "requests==2.0.0 is not in the lock"),
        ("aiofiles==26.0.0\n", "aiofiles resolved to 26.0.0 but the lock pins 25.1.0"),
        ("unhashed==1.0\n", "unhashed==1.0 has no --hash lines in the lock"),
        ("", "names no packages"),
    ],
)
def test_anything_outside_the_committed_lock_fails_the_build(resolved, complaint):
    with pytest.raises(SystemExit) as error:
        hashed_subset.hashed_subset(LOCK, resolved)
    assert complaint in str(error.value)


def test_the_committed_lock_carries_a_hash_for_every_requirement():
    """`pip install --require-hashes -r requirements.txt` is how every CI job
    installs the backend; a lock regenerated without backend/bin/
    compile-requirements would drop the hashes (or the Linux-only packages a
    universal resolution adds) and only fail there."""
    lock = hashed_subset.parse_lock((BACKEND / "requirements.txt").read_text(encoding="utf-8"))
    assert len(lock) > 100
    assert [name for name, (_version, entry) in lock.items() if len(entry) < 2] == []
    # The packages a macOS-only resolution leaves out.
    assert "greenlet" in lock
    # Hash mode rejects a dependency missing from the file; pip-tools needs these.
    assert {"pip", "setuptools"} <= set(lock)

    # The runtime subset's top-level names must all be resolvable from the lock.
    runtime = [
        hashed_subset.normalize(line.split("[")[0].split(">")[0].split("=")[0].strip())
        for line in (BACKEND / "requirements.docker.in").read_text(encoding="utf-8").splitlines()
        if line.strip() and not line.startswith("#")
    ]
    assert [name for name in runtime if name not in lock] == []
